func (catalog_fr) Locale() language.Tag { return loc_fr }

func (catalog_fr) Translator() locales.Translator { return tr_fr }

func (catalog_fr) String(tik string, args ...any) string {
	b := poolBufGet()
	defer poolBufPut(b)
	f := writers_fr[tik]
	if f == nil {
		_, _ = MissingTranslation(b, loc_fr, tik, args...)
	} else {
		_, _ = f(b, args...)
	}
	return b.String()
}

func (catalog_fr) Write(
	writer io.Writer, tik string, args ...any,
) (written int, err error) {
	f := writers_fr[tik]
	if f == nil {
		return MissingTranslation(writer, loc_fr, tik, args...)
	}
	return f(writer, args...)
}
